// === Tab: mySketch ===
let Shader,displayShader;
let prev,curr,canv;
let tiles;
function preload() {
	Shader=getShader(this._renderer);
	displayShader=getDisplayShader(this._renderer);
	tiles=loadImage("https://openprocessing.org/sketch/1406886/files/tiles.jpg");
}

function setup() {
	canv=createCanvas(1112,834,WEBGL);
	noStroke();
	prev=createGraphics(width,height);
	curr=createGraphics(width,height);
	background(0);
}

function draw() {
	shader(Shader);
	Shader.setUniform('prev',prev);
	Shader.setUniform('curr',curr);
	if (frameCount%3==0) {Shader.setUniform('mouse',[random(width),random(height),1]);}
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {Shader.setUniform('mouse',[(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),1]);}
	background(0);
	rect(0,0,width,height);
	curr.image(canv,0,0,width,height);
	let tmp=prev;
	prev=curr;
	curr=tmp;

	shader(displayShader);
	displayShader.setUniform('heightMap',curr);
	displayShader.setUniform('tex',tiles);
	background(0);
	rect(0, 0, width, height);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

function getDisplayShader(_renderer) {
	const vvert = `
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`;
	const ffrag = `
		precision highp float;
		varying vec2 vTexCoord;
		const float width=${windowWidth}.;
		const float height=${windowHeight}.;
		uniform sampler2D heightMap;
		uniform sampler2D tex;
		uniform vec3 mouse;
		void main() {
			float x=vTexCoord.x*width;
			float y=height-vTexCoord.y*height;
			float offX=texture2D(heightMap,vec2((x-1.)/width,y/height)).r-texture2D(heightMap,vec2((x+1.)/width,y/height)).r;
			float offY=texture2D(heightMap,vec2(x/width,(y-1.)/height)).r-texture2D(heightMap,vec2(x/width,(y+1.)/height)).r;
			gl_FragColor=vec4((texture2D(tex,vec2(x/width+offX,y/height+offY)).rgb+vec3(offX))/4.+0.3,1.);
		}
	`;
	return createShader(vvert, ffrag);
}

function getShader(_renderer) {
	const vert = `
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`;
	const frag = `
		precision highp float;
		varying vec2 vTexCoord;
		const float width=${windowWidth}.;
		const float height=${windowHeight}.;
		uniform sampler2D prev;
		uniform sampler2D curr;
		uniform vec3 mouse;
		void main() {
			float x=vTexCoord.x*width;
			float y=height-vTexCoord.y*height;
			float val=((
			texture2D(prev,vec2(x/width,(y-1.)/height)).r+
			texture2D(prev,vec2((x+1.)/width,y/height)).r+
			texture2D(prev,vec2(x/width,(y+1.)/height)).r+
			texture2D(prev,vec2((x-1.)/width,y/height)).r
			)/2.-texture2D(curr,vec2(x/width,y/height)).r)*.99;
			if (mouse.z==1.&&mouse.x>x-2.&&mouse.x<x+2.&&mouse.y>y-2.&&mouse.y<y+2.) {val=1.;}
			//val=1.;
			gl_FragColor=vec4(vec3(val),1.);
		}
	`;
	return createShader(vert, frag);
}

